 49	// Parser is a reusable parser. The zero value is ready for use.
 50	type Parser struct {
 51		lexer            *Lexer
 52		current, stashed Token
 53		hasStash         bool
 54		err              *file.Error
 55		config           *conf.Config
 56		depth            int  // predicate call depth
 57		nodeCount        uint // tracks number of AST nodes created
 58	}
